  ```js
  import { appendFileSync, statSync, existsSync, unlinkSync, renameSync } from 'node:fs';

  let config = {
    path: 'app.log',
    maxBytes: 1_048_576,
    maxFiles: 5,
  };

  export function configure(options = {}) {
    config = { ...config, ...options };
  }

  export function write(line) {
    appendFileSync(config.path, line + '\n');
    const { size } = statSync(config.path);
    if (size >= config.maxBytes) {
      rotate();
    }
  }

  export function rotate() {
    if (!existsSync(config.path)) return;

    const oldest = `${config.path}.${config.maxFiles}`;
    if (existsSync(oldest)) {
      unlinkSync(oldest);
    }

    for (let n = config.maxFiles - 1; n >= 1; n--) {
      const src = `${config.path}.${n}`;
      if (existsSync(src)) {
        renameSync(src, `${config.path}.${n + 1}`);
      }
    }

    renameSync(config.path, `${config.path}.1`);
  }
  ```
