  import { test } from 'node:test';
  import assert from 'node:assert';
  import { mkdtempSync, readFileSync, existsSync, readdirSync } from 'node:fs';
  import { tmpdir } from 'node:os';
  import { join } from 'node:path';
  import { configure, write, rotate } from '../src/logrotate.js';

  function freshLogPath() {
    const dir = mkdtempSync(join(tmpdir(), 'logrotate-'));
    return join(dir, 'app.log');
  }

  test('write appends lines to the configured path', () => {
    const path = freshLogPath();
    configure({ path, maxBytes: 1_048_576, maxFiles: 5 });
    write('one');
    write('two');
    const content = readFileSync(path, 'utf8');
    assert.strictEqual(content, 'one\ntwo\n');
  });

  test('write triggers rotate once the configured size is exceeded', () => {
    const path = freshLogPath();
    configure({ path, maxBytes: 10, maxFiles: 5 });
    write('this line is over ten bytes');
    assert.ok(existsSync(`${path}.1`));
    assert.ok(!existsSync(path));
  });

  test('rotate keeps at most maxFiles rotated files and drops the oldest', () => {
    const path = freshLogPath();
    configure({ path, maxBytes: 1_048_576, maxFiles: 2 });

    write('gen0');
    rotate();
    write('gen1');
    rotate();
    write('gen2');
    rotate();

    assert.ok(existsSync(`${path}.1`));
    assert.ok(existsSync(`${path}.2`));
    assert.ok(!existsSync(`${path}.3`));

    const dir = path.slice(0, path.lastIndexOf('/'));
    const rotatedCount = readdirSync(dir).filter((f) => f.startsWith('app.log.')).length;
    assert.strictEqual(rotatedCount, 2);
  });
