  import { test } from 'node:test';
  import assert from 'node:assert';
  import { mkdtempSync, readFileSync, existsSync } from 'node:fs';
  import { tmpdir } from 'node:os';
  import { join } from 'node:path';
  import { configure, write, rotate } from '../src/logrotate.js';

  test('no line is lost when writes race a rotation', async () => {
    const dir = mkdtempSync(join(tmpdir(), 'logrotate-concurrent-'));
    const path = join(dir, 'app.log');
    configure({ path, maxBytes: 1_048_576, maxFiles: 5 });

    const totalWrites = 50;
    const rotateAfter = 25;

    const writers = Array.from({ length: totalWrites }, (_, i) =>
      new Promise((resolve) => {
        setImmediate(() => {
          write(`line-${i}`);
          if (i === rotateAfter) {
            rotate();
          }
          resolve();
        });
      })
    );

    await Promise.all(writers);

    let allLines = '';
    if (existsSync(`${path}.1`)) {
      allLines += readFileSync(`${path}.1`, 'utf8');
    }
    if (existsSync(path)) {
      allLines += readFileSync(path, 'utf8');
    }

    const lineCount = allLines.split('\n').filter((l) => l.length > 0).length;
    assert.strictEqual(lineCount, totalWrites);
  });
